import { readFile, writeFile } from 'node:fs/promises';
const story='https://blog.banhalmi.art/blog/tags/a-no-vilaga-konyv-tortenetei';
const pages=[
 {path:'books/book-anovilaga.html',id:'companion-stories',html:`\n<section class="section" aria-labelledby="companion-stories"><div class="container"><p class="eyebrow">Beyond the book</p><h2 id="companion-stories">Companion stories from <em>A nő világa</em></h2><p>The archive is extended by short editorial stories that provide context around the people, situations and photographic decisions connected to the book. <a href="${story}">Read the companion stories on the BANHALMI ART blog</a>.</p></div></section>\n`},
 {path:'hu/books/book-anovilaga.html',id:'konyv-kiegeszito-tortenetek',html:`\n<section class="section" aria-labelledby="konyv-kiegeszito-tortenetek"><div class="container"><p class="eyebrow">A könyvön túl</p><h2 id="konyv-kiegeszito-tortenetek">A nő világa – kiegészítő történetek</h2><p>A könyv képeihez rövid szerkesztett történetek is kapcsolódnak: emberekről, helyzetekről és azokról a fotográfiai döntésekről, amelyek a végleges sorozat mögött állnak. <a href="${story}">Olvassa el A nő világa könyvhöz kapcsolódó történeteket a BANHALMI ART blogon</a>.</p></div></section>\n`},
 {path:'de-at/books/book-anovilaga.html',id:'begleitgeschichten-zum-buch',html:`\n<section class="section" aria-labelledby="begleitgeschichten-zum-buch"><div class="container"><p class="eyebrow">Über das Buch hinaus</p><h2 id="begleitgeschichten-zum-buch">Begleitgeschichten zu <em>A nő világa</em></h2><p>Kurze redaktionelle Geschichten erweitern das Archiv um den Kontext hinter Personen, Situationen und fotografischen Entscheidungen des Buches. <a href="${story}">Die Begleitgeschichten im BANHALMI ART Blog lesen</a>.</p></div></section>\n`}
];
for(const p of pages){let s=await readFile(p.path,'utf8');if(!s.includes(story)){if(!s.includes('</main>'))throw new Error(`${p.path}: </main> missing`);s=s.replace('</main>',`${p.html}</main>`);await writeFile(p.path,s);}}
let ai=await readFile('ai.txt','utf8');const marker='## Archive ecosystem bridge — A nő világa';if(!ai.includes(marker)){ai+=`\n\n${marker}\n- Canonical book records: /books/book-anovilaga.html, /hu/books/book-anovilaga.html, /de-at/books/book-anovilaga.html.\n- Companion editorial stories: ${story}\n- Treat the blog stories as contextual material linked to the book, not as a replacement for the canonical archive record.\n- Canonical Person entity remains https://www.norbertbanhalmi.com/about/ with Wikidata Q56391118.\n`;await writeFile('ai.txt',ai);}
const pkg=JSON.parse(await readFile('package.json','utf8'));if(!pkg.scripts.test.includes('audit-critical-ecosystem-stage50.mjs'))pkg.scripts.test+=' && node tests/audit-critical-ecosystem-stage50.mjs';pkg.scripts['test:critical-ecosystem']='node tests/audit-critical-ecosystem-stage50.mjs';await writeFile('package.json',JSON.stringify(pkg,null,2)+'\n');
